/* Brandell, 3 Diabetes Mellitus Pharmacology - 2026.pptx.
 * Objectives follow the supplied order. Historical slides are excluded.
 * Small FDA/ADA additions are labeled where an objective exceeds the slides.
 */
(function () {
  "use strict";
  function q(prompt, answer, wrong, explanation) { return {prompt:prompt, choices:[answer].concat(wrong), correct:0, explanation:explanation}; }
  function u(title, html, tags, test, apply) { return {title:title, html:html, tags:tags, test:test, apply:apply}; }
  var sections = [];
  function add(id, title, description, units) {
    var s = {id:id, title:title, description:description, cards:[], test:[], apply:[]};
    units.forEach(function (unit, ci) {
      s.cards.push({title:unit.title, html:unit.html, coverage:unit.tags});
      ["test","apply"].forEach(function (mode) { unit[mode].forEach(function (question) { question.card=ci; s[mode].push(question); }); });
    });
    sections.push(s);
  }
  function table(headings, rows) { return '<table><thead><tr>'+headings.map(function(x){return '<th>'+x+'</th>';}).join('')+'</tr></thead><tbody>'+rows.map(function(row){return '<tr>'+row.map(function(x){return '<td>'+x+'</td>';}).join('')+'</tr>';}).join('')+'</tbody></table>'; }
  function names(title, rows, tag, className) {
    var pool=["Glucophage","Januvia","Actos","Jardiance","Victoza","Humalog","Tradjenta","Glucotrol"];
    var classes=["Biguanide","Sulfonylurea","GLP-1 receptor agonist","DPP-4 inhibitor","SGLT2 inhibitor","Thiazolidinedione (TZD)","Meglitinide","Alpha-glucosidase inhibitor","Dual GIP/GLP-1 receptor agonist","Rapid-acting insulin","Short-acting insulin","Intermediate-acting insulin","Long-acting basal insulin","Ultra-long-acting basal insulin"];
    var alternatives=classes.filter(function(x){return x!==className;}).slice(0,3);
    return u(title,table(["Generic/formulation","Trade name"],rows),[tag].concat(rows.map(function(row){return tag+':'+row[0];})),rows.map(function(row){
      if(className==="Meglitinide"||className==="Alpha-glucosidase inhibitor") return q('Which class contains '+row[0]+' ('+row[1]+')?',className,alternatives,'Both names are supplied; recognize the '+className+' class.');
      var wrong=pool.filter(function(x){return row[1].indexOf(x)<0;}).slice(0,3);
      return q('Which trade name matches '+row[0]+'?',row[1],wrong,row[0]+' is marketed as '+row[1]+'.');
    }),[q('A prescription lists '+rows[0][0]+' ('+rows[0][1]+'). Which class should you recognize?',className,alternatives,rows[0][0]+' belongs to '+className+'.')]);
  }
  var ada='<a href="https://doi.org/10.2337/dc26-s009" target="_blank" rel="noopener noreferrer">ADA pharmacologic guidance</a>';
  var tirzepatideLabel='<a href="https://dailymed.nlm.nih.gov/dailymed/fda/fdaDrugXsl.cfm?setid=d2d7da5d-ad07-4228-955f-cf7e355c8cc0" target="_blank" rel="noopener noreferrer">Tirzepatide labeling</a>';
  add("01-metformin","1. Biguanide: metformin","Drug-class objectives: names, mechanism/benefits, adverse effects/contraindications, efficacy, and indications. Slides 13–17.",[
    names("Metformin = Glucophage",[["Metformin","Glucophage"]],"metformin-names","Biguanide"),
    u("Mechanism and benefit",'<p><strong>↓ hepatic glucose production; ↓ GI glucose absorption; ↑ insulin sensitivity/peripheral uptake.</strong> It does not directly stimulate insulin secretion.</p><p>Low hypoglycemia risk alone; weight neutral to modest loss. IR and ER formulations are available.</p>',["metformin-moa","metformin-benefits"],[q("Which mechanism fits metformin?","Less liver glucose production and greater insulin sensitivity",["Glucose-independent insulin release","Blocking renal glucose reabsorption","Activating both GIP and GLP-1 receptors"],"Metformin reduces production and improves glucose utilization rather than forcing insulin release.")],[q("A T2DM patient wants an oral option with low intrinsic hypoglycemia risk and little weight gain. Which mechanism fits metformin?","Reduced hepatic glucose production with improved sensitivity",["Insulin secretion regardless of glucose","Providing injected basal insulin","Delayed intestinal carbohydrate digestion alone"],"Metformin has low hypoglycemia risk as monotherapy and weight neutrality/modest loss.")]),
    u("GI effects, B12, and lactic acidosis",'<p>Common: <strong>diarrhea, nausea/vomiting, metallic taste</strong>. Start low/titrate gradually; ER may improve tolerance.</p><p>Long-term use can cause <strong>B12 deficiency</strong>; consider periodic monitoring. <strong>Lactic acidosis</strong> is rare but serious and carries a boxed warning.</p>',["metformin-gi","metformin-b12","metformin-lactic"],[q("Which chronic adverse effect merits periodic consideration with metformin?","Vitamin B12 deficiency",["Severe hypoglycemia as the usual monotherapy effect","Predictable major weight gain","Medullary thyroid carcinoma as a proven human effect"],"Metformin can reduce B12 over time; GI effects are common and lactic acidosis rare but serious.")],[q("A patient has troublesome diarrhea after starting metformin. Which lecture-based adjustment may improve tolerability?","Slow titration and/or ER formulation",["Immediately double the dose","Treat it as evidence that all diabetes drugs are contraindicated","Add another glucose-independent secretagogue to treat diarrhea"],"Starting low and using ER when appropriate can reduce GI burden.")]),
    u("Renal and contrast precautions",'<p><strong>Do not use if eGFR &lt;30</strong>; starting at 30–45 is not recommended. If eGFR falls below 45, reassess benefit/risk.</p><p>Hold for iodinated contrast in at-risk patients; reassess renal function after <strong>48 hours</strong> before restarting. The lecture does not say every contrast study requires a hold.</p>',["metformin-renal","metformin-contrast"],[q("Which renal finding contraindicates metformin in the lecture?","eGFR below 30",["Any eGFR below 90","A normal creatinine alone","Every eGFR from 45 to 60"],"Do not use below 30; initiation at 30–45 is not recommended."),q("What precedes restarting metformin after an indicated contrast hold?","Renal reassessment after 48 hours",["Restarting immediately regardless of function","Waiting exactly one year","Using a normal A1C as a substitute for kidney assessment"],"Recheck renal function before restarting in an at-risk patient.")],[q("A patient considered for metformin has eGFR 25. Which choice fits the lecture?","Do not start metformin",["Start normally because it is weight neutral","Start normally because hypoglycemia risk is low","Use renal function only after several months"],"The renal contraindication applies despite other advantages.")]),
    u("Efficacy and indications",'<p>A1C reduction approximately <strong>1–1.5 percentage points</strong>. Approved for T2DM, including age ≥10 in the lecture.</p><p>Lecture-listed off-label uses: <strong>prediabetes prevention, PCOS, and gestational diabetes</strong>. In pregnancy it crosses the placenta; insulin is preferred. Low relative infant exposure is noted in breastmilk.</p>',["metformin-efficacy","metformin-indications","metformin-offlabel"],[q("What A1C reduction is expected from metformin in the lecture?","About 1–1.5 percentage points",["About 0.1 percentage point","About 3–4 percentage points in everyone","No glycemic effect"],"This is an approximate effect, influenced by starting A1C and response."),q("Which use is listed as off-label rather than routine approved T2DM treatment?","PCOS",["T2DM in an eligible patient","Replacement of insulin in every T1DM patient","Immediate treatment of DKA"],"PCOS, prediabetes prevention, and GDM are the slide-listed off-label contexts.")],[q("A patient with PCOS asks why metformin is being discussed despite no established T2DM. How is this explained within the lecture?","PCOS is a listed off-label use",["Metformin is insulin replacement","Metformin directly activates GIP receptors","PCOS makes renal precautions irrelevant"],"Off-label indication does not remove the need for appropriate safety assessment.")])
  ]);
  add("02-sulfonylureas","2. Sulfonylureas","Drug-class objectives: all three drugs, mechanism/indications, harms/contraindications, and efficacy. Slides 46–50.",[
    names("The three sulfonylureas",[["Glyburide","Micronase / Diabeta"],["Glipizide","Glucotrol"],["Glimepiride","Amaryl"]],"su-names","Sulfonylurea"),
    u("Insulin secretion regardless of glucose",'<p>Stimulate functioning pancreatic beta cells to release insulin <strong>regardless of glucose level</strong>. Used for T2DM; effectiveness can decline as beta-cell function fails.</p><p>A1C reduction <strong>~1–1.5 points</strong>. Inexpensive, oral, effective; no demonstrated cardiovascular/kidney benefit in the lecture.</p>',["su-moa","su-indications","su-efficacy","su-place"],[q("Why do sulfonylureas cause hypoglycemia?","They stimulate insulin release regardless of glucose",["They only release insulin when glucose is high","They have no insulin effect","They require urine glucose before acting"],"Glucose-independent secretion creates risk when food/glucose availability falls."),q("What A1C reduction is expected with sulfonylureas?","~1–1.5 points",["~0.1–0.2 points","~4 points in every patient","No reduction"],"They are effective but lack the cardiorenal benefits of selected newer agents.")],[q("A patient needs an inexpensive oral T2DM option, has functioning beta cells, and can accept hypoglycemia/weight risks. Which class fits the slide’s low-cost option?","Sulfonylurea",["Insulin is an oral drug","A GLP-1 injectable is always the cheapest choice","A DPP-4 drug produces the same strong hypoglycemia mechanism"],"Sulfonylureas are inexpensive/effective, with important safety tradeoffs.")]),
    u("Hypoglycemia, weight gain, and high-risk histories",'<p>Main harms: <strong>hypoglycemia and weight gain</strong>. Glyburide has greater prolonged-low risk; generally avoid in older adults/renal impairment.</p><p>G6PD deficiency: hemolytic-anemia caution. Sulfonamide-antibiotic cross-reactivity is unlikely; do not equate every sulfa-antibiotic allergy with a class contraindication.</p><p>Overdose can cause <strong>prolonged, recurrent lows</strong>, requiring extended monitoring. These secretagogues are not substitutes for insulin in T1DM.</p>',["su-hypoglycemia-weight","glyburide-avoid","su-g6pd","su-sulfa","su-recurrence"],[q("Which sulfonylurea should generally be avoided in older adults or renal impairment?","Glyburide",["Glipizide is always more prolonged than glyburide","All GLP-1 drugs are sulfonylureas","Linagliptin"],"Glyburide carries greater risk of prolonged hypoglycemia."),q("Which special caution is named for G6PD deficiency?","Possible hemolytic anemia",["A guaranteed need for renal glucose excretion","A proven thyroid C-cell tumor in every patient","No relevant sulfonylurea risk"],"Consider an alternative because hemolysis can occur.")],[q("An older patient with CKD improves after treatment for a glyburide-associated low. What remains important?","Risk of prolonged/recurrent hypoglycemia and continued monitoring",["One corrected value proves the drug effect is over","The weight-gain effect prevents recurrence","Renal impairment shortens the risk period"],"Long action and impaired clearance can outlast initial glucose replacement.")])
  ]);
  add("03-glp1","3. GLP-1 receptor agonists","Drug-class objectives: names, mechanism/benefits, routes/frequencies, efficacy, and adverse reactions/contraindications. Slides 22–28.",[
    names("Recognize each GLP-1 formulation",[["Semaglutide (SQ)","Ozempic"],["Semaglutide (oral)","Rybelsus"],["Exenatide","Byetta"],["Exenatide ER","Bydureon BCise"],["Liraglutide","Victoza"],["Dulaglutide","Trulicity"]],"glp-names","GLP-1 receptor agonist"),
    u("Incretin action and benefits",'<p><strong>↑ glucose-dependent insulin; ↓ inappropriate glucagon; slower gastric emptying; greater satiety/less intake.</strong></p><p>A1C reduction <strong>~1–2 points</strong>; low intrinsic hypoglycemia risk and weight loss. Liraglutide, semaglutide (SQ/oral), and dulaglutide have demonstrated MACE reduction in the lecture.</p>',["glp-moa","glp-weight-hypo","glp-efficacy","glp-cv"],[q("Which mechanism describes GLP-1 receptor agonists?","Glucose-dependent insulin, less glucagon, slower emptying, and more satiety",["Insulin release regardless of glucose only","Renal glucose wasting only","Breaking down endogenous incretins"],"Receptor activation improves glycemia and reduces appetite; glucose dependence limits intrinsic low risk."),q("What class A1C reduction is given in the lecture?","~1–2 points",["No reduction","~0.1 point","~5 points reliably"],"Potency varies by agent, dose, and starting A1C.")],[q("A T2DM patient with ASCVD also values weight loss. Which named GLP-1 agents have demonstrated CV benefit in the lecture?","Liraglutide, semaglutide, and dulaglutide",["Every exenatide formulation is automatically proven identical","Saxagliptin and alogliptin","Glyburide and NPH"],"Choose an agent with demonstrated benefit rather than assuming every member has identical outcomes.")]),
    u("Route and frequency are formulation-specific",table(["Agent","Route/frequency"],[["Liraglutide","SQ daily"],["Semaglutide Ozempic","SQ weekly"],["Semaglutide Rybelsus","Oral daily"],["Dulaglutide","SQ weekly"],["Exenatide Byetta","SQ twice daily"],["Exenatide ER Bydureon BCise","SQ weekly"]]),["glp-administration"],[q("Which semaglutide route/frequency pairing matches the lecture?","Ozempic SQ weekly; Rybelsus oral daily",["Both SQ twice daily","Ozempic oral daily; Rybelsus SQ weekly","Both oral weekly"],"The same generic has different formulations and schedules."),q("Which GLP-1 agent is SQ daily?","Liraglutide",["Dulaglutide","Exenatide ER","SQ semaglutide"],"Liraglutide is daily; the other listed choices are weekly."),q("How do Byetta and Bydureon BCise differ?","Byetta SQ twice daily; Bydureon BCise SQ weekly",["Both oral daily","Both SQ daily","Byetta weekly; BCise twice daily"],"Exenatide immediate and extended release have different schedules.")],[q("A patient wants a weekly GLP-1 injection rather than daily/twice-daily dosing. Which listed schedule fits?","Dulaglutide SQ weekly",["Liraglutide SQ daily","Byetta SQ twice daily","Rybelsus oral daily"],"Choose the formulation and frequency matching the preference.")]),
    u("GI effects and pancreatitis warnings",'<p>Common <strong>nausea, vomiting, diarrhea/constipation</strong>, especially with initiation/escalation. Titrate slowly; smaller meals/stop when full can help.</p><p>Severe GI losses can cause dehydration/AKI. Persistent severe abdominal pain ± back radiation raises pancreatitis concern: discontinue if suspected; consider alternatives with a pancreatitis history. Injection reactions can occur; rotate sites.</p>',["glp-gi","glp-aki","glp-pancreatitis","glp-injection"],[q("Which symptom requires evaluation for pancreatitis during GLP-1 therapy?","Persistent severe abdominal pain, possibly radiating to the back",["Only mild fullness after a meal","Only a routine desire for less food","Only normal glucose readings"],"Suspected pancreatitis warrants discontinuation and evaluation.")],[q("After a GLP-1 dose escalation, a patient develops persistent vomiting and reduced fluid intake. What complication needs attention?","Volume depletion and possible AKI",["Guaranteed absence of renal risk because most agents need no dose adjustment","Expected symptoms that never require assessment","A reason to double the dose"],"GI fluid losses can cause kidney injury even without a routine dose-adjustment requirement.")]),
    u("Contraindications and renal differences",'<p>For products with the thyroid C-cell boxed warning, <strong>personal/family MTC or MEN2 is a contraindication</strong>. Rodent findings prompted the warning; human relevance is unknown.</p><p>Renal restrictions are agent-specific: most do not need routine renal dose adjustment; <strong>exenatide has greater restrictions</strong>. Check the particular formulation rather than giving the class a single cutoff.</p>',["glp-mtc-men2","glp-agent-renal"],[q("Which history contraindicates a GLP-1 product carrying the thyroid C-cell warning?","Personal/family MTC or MEN2",["Every benign thyroid nodule automatically","Any family history of T2DM","A normal retinal exam"],"Use the specific MTC/MEN2 warning rather than confusing all thyroid conditions."),q("Which named GLP-1 drug has greater renal restrictions?","Exenatide",["Every member has no renal considerations","Insulin lispro","Saxagliptin"],"Exenatide requires particular formulation-specific renal review.")],[q("A patient has a personal history of MTC and is considered for semaglutide. What safety finding is decisive?","The MTC history contraindicates this warned product",["Low hypoglycemia risk overrides the contraindication","Weight loss eliminates the warning","Only fasting glucose determines safety"],"Benefit does not override the MTC/MEN2 contraindication.")])
  ]);
  add("04-tirzepatide","4. Dual GIP/GLP-1: tirzepatide","Drug-class objectives. Slide 30 plus labeled FDA efficacy/safety additions.",[
    names("One ingredient, two named brands",[["Tirzepatide","Mounjaro / Zepbound"]],"tirzepatide-names","Dual GIP/GLP-1 receptor agonist"),
    u("Dual action, weekly SQ, very high efficacy",'<p>Activates <strong>GIP and GLP-1</strong>: glucose-dependent insulin release, less glucagon, slower emptying, and more satiety. Given <strong>SQ once weekly</strong>; significant weight loss.</p><p><strong>Label efficacy addition:</strong> about 2 points or more A1C lowering in trials; one trial reported ~2.1–2.4 points across studied doses. Response varies; this is not a guaranteed reduction. '+tirzepatideLabel+'</p>',["tirzepatide-moa","tirzepatide-frequency","tirzepatide-efficacy","tirzepatide-weight"],[q("Which receptor pair does tirzepatide activate?","GIP and GLP-1",["DPP-4 and SGLT2","Insulin and glucagon receptors equally","Only intestinal alpha-glucosidase"],"Tirzepatide is the dual incretin agonist."),q("Which efficacy/frequency description fits tirzepatide?","Very high efficacy, roughly 2 points or more in trials; SQ weekly",["No glycemic effect; oral daily","Low efficacy; SQ twice daily","Fixed 5-point reduction; IV monthly"],"The numeric estimate supplements the slide’s qualitative very-high efficacy.")],[q("A patient prioritizes substantial A1C lowering and weight loss and accepts a weekly injection. Which dual-receptor drug fits?","Tirzepatide",["Sitagliptin","Acarbose","NPH"],"Dual GIP/GLP-1 activation offers very high glycemic efficacy and weight benefit.")]),
    u("Safety addition for the requested objective",'<p><strong>Label addition:</strong> GI symptoms, dehydration/AKI, pancreatitis concerns; low intrinsic hypoglycemia risk increases with insulin/secretagogues.</p><p>Contraindicated with <strong>MTC/MEN2 or serious hypersensitivity</strong>; not recommended in severe gastroparesis. '+tirzepatideLabel+'</p>',["tirzepatide-adverse","tirzepatide-contra","tirzepatide-combination-hypo"],[q("Which history contraindicates tirzepatide?","MTC/MEN2 or serious hypersensitivity to the drug",["Obesity alone","A desire to lose weight","All oral glucose-lowering therapy"],"The product-specific safety objective needs the labeled contraindications.")],[q("A patient starts tirzepatide while also using insulin and a sulfonylurea. What deserves particular review?","Hypoglycemia risk from the combined regimen",["The combination guarantees no hypoglycemia","Tirzepatide replaces glucose monitoring automatically","All insulin must be discontinued regardless of diagnosis"],"Low intrinsic risk does not remove insulin/secretagogue-related lows.")])
  ]);
  add("05-dpp4","5. DPP-4 inhibitors","Drug-class objectives: all four names, mechanism/efficacy, contraindications and harms. Slides 32–37.",[
    names("The four DPP-4 inhibitors",[["Sitagliptin","Januvia"],["Saxagliptin","Onglyza"],["Linagliptin","Tradjenta"],["Alogliptin","Nesina"]],"dpp-names","DPP-4 inhibitor"),
    u("Preserve endogenous incretins",'<p>DPP-4 normally breaks down GLP-1/GIP. Inhibition <strong>prolongs endogenous incretin activity</strong>.</p><p>A1C reduction <strong>~0.5–0.8 points</strong>; weight neutral, low low-glucose risk alone. Most need CKD dose adjustment; <strong>linagliptin does not</strong>.</p>',["dpp-moa","dpp-efficacy","dpp-weight-hypo","dpp-renal"],[q("How do DPP-4 inhibitors work?","Reduce breakdown of endogenous incretins",["Directly activate both GIP/GLP-1 receptors","Force insulin secretion regardless of glucose","Block intestinal carbohydrate enzymes"],"They preserve GLP-1/GIP rather than injecting a receptor agonist."),q("Which DPP-4 drug does not require renal dose adjustment?","Linagliptin",["Sitagliptin","Saxagliptin","Alogliptin"],"Linagliptin is the renal-adjustment exception in the lecture."),q("What A1C reduction is expected for DPP-4 inhibitors?","~0.5–0.8 points",["~2–3 points reliably","No reduction","~4 points"],"They provide modest glycemic efficacy.")],[q("A patient with CKD needs a weight-neutral DPP-4 option and renal dosing is a concern. Which listed drug avoids routine renal adjustment?","Linagliptin",["Sitagliptin without considering its dose","Glyburide as a DPP-4 drug","Tirzepatide as a DPP-4 drug"],"Recognize the within-class renal difference.")]),
    u("Rare reactions, HF cautions, and a combination to avoid",'<p>Rare: <strong>pancreatitis, severe joint pain, bullous pemphigoid, hypersensitivity</strong>. Stop/evaluate suspected pancreatitis; serious drug hypersensitivity precludes reuse.</p><p>No demonstrated CV benefit in the lecture. <strong>Saxagliptin increases HF hospitalization risk; saxagliptin/alogliptin labeling carries HF warnings.</strong></p><p>Do not combine with a GLP-1 RA or dual GIP/GLP-1 agonist: no meaningful extra glycemic benefit.</p>',["dpp-adverse","dpp-hypersensitivity","dpp-hf","dpp-no-combination"],[q("Which combination should generally be avoided because there is no meaningful added glucose benefit?","DPP-4 inhibitor plus GLP-1–based therapy",["Metformin with an appropriately selected add-on","Basal and prandial insulin in T1DM","Lifestyle with pharmacologic treatment"],"Overlapping incretin approaches add little benefit."),q("Which two DPP-4 drugs have FDA-label HF warnings in the lecture?","Saxagliptin and alogliptin",["Linagliptin and metformin","Semaglutide and dulaglutide","Empagliflozin and dapagliflozin"],"Saxagliptin's trial HF signal and labeling cautions matter to selection.")],[q("A patient taking saxagliptin develops heart failure and needs medication review. Which class-specific concern matters?","HF hospitalization risk and lack of demonstrated CV benefit",["Saxagliptin is the preferred HF-benefit agent","DPP-4 therapy treats fluid retention like an SGLT2 agent","Add semaglutide without reviewing the DPP-4 combination"],"Review the HF warning and choose therapy with appropriate benefit.")])
  ]);
  add("06-sglt2","6. SGLT2 inhibitors","Drug-class objectives: all four names, mechanism/benefits/efficacy, contraindications and adverse effects. Slides 39–44.",[
    names("The four SGLT2 inhibitors",[["Canagliflozin","Invokana"],["Dapagliflozin","Farxiga"],["Empagliflozin","Jardiance"],["Ertugliflozin","Steglatro"]],"sglt-names","SGLT2 inhibitor"),
    u("Kidney glucose loss and cardiorenal benefits",'<p>Block proximal-tubule glucose reabsorption → <strong>glucosuria and osmotic diuresis</strong>, independent of insulin.</p><p>A1C reduction <strong>~0.5–1 point</strong>; modest weight/BP reduction, low hypoglycemia risk alone. Selected agents have HF (HFrEF/HFpEF), CKD, and CV-risk benefits.</p><p>Lower eGFR reduces glucose-lowering effect, while cardiorenal benefits may persist. Renal use limits are <strong>agent/indication-specific</strong>.</p>',["sglt-moa","sglt-efficacy","sglt-weight-hypo","sglt-cardiorenal","sglt-renal"],[q("Which mechanism fits SGLT2 inhibition?","Less renal glucose reabsorption and more urinary glucose excretion",["More glucose absorption from the bowel","Insulin release regardless of glucose","Only prolonged endogenous GLP-1"],"Proximal-tubule transport inhibition causes glucosuria/osmotic diuresis."),q("What happens as renal function declines?","Glucose-lowering efficacy falls, but cardiorenal benefit may persist",["All benefits necessarily disappear at the same threshold","A1C lowering always increases","Renal function is irrelevant"],"Do not equate reduced glucose effect with absence of cardiorenal benefit.")],[q("A T2DM patient has heart failure. Which class with demonstrated HF benefit should be considered, if appropriate for the patient?","SGLT2 inhibitor",["TZD for edema","Saxagliptin as a proven HF-benefit drug","Glyburide for kidney protection"],"Select an agent with demonstrated benefit and appropriate renal/safety eligibility.")]),
    u("Infections, fluid loss, and euglycemic DKA",'<p>Genital mycotic infections, polyuria, volume depletion/hypotension; rare Fournier gangrene.</p><p><strong>Euglycemic DKA</strong> can occur with normal/mildly elevated glucose. Risk rises with acute illness, fasting, surgery, or substantial insulin reduction. Do not use this class as an insulin substitute in insulin-deficient disease.</p><p>Hold before surgery: <strong>3 days for most; 4 days for ertugliflozin</strong>. Product/indication renal restrictions must be checked rather than using one universal cutoff.</p>',["sglt-infections","sglt-volume","sglt-edka","sglt-hold","sglt-contra-review"],[q("Which feature makes SGLT2-associated DKA easy to miss?","Glucose may be normal or only mildly elevated",["It cannot occur during fasting","It requires glucose above 600 in every case","It is excluded by ketones"],"Recognize euglycemic DKA rather than relying on very high glucose."),q("Which preoperative hold schedule is given?","Most 3 days; ertugliflozin 4 days",["All only the morning of surgery","All 1 day","Ertugliflozin 1 day; others 4 days"],"The lecture distinguishes ertugliflozin's longer hold.")],[q("A fasting, ill patient on an SGLT2 drug develops symptoms concerning for ketoacidosis with glucose only mildly high. What is the appropriate concern?","Possible euglycemic DKA despite the glucose value",["DKA is excluded because glucose is not markedly high","Only routine thirst without need for assessment","A reason to reduce insulin drastically without evaluation"],"The risk context and ketotic illness matter even without extreme hyperglycemia.")])
  ]);
  add("07-tzd","7. TZDs / glitazones","Drug-class objectives: names, efficacy, and adverse effects/contraindications. Slides 52–54.",[
    names("The two TZDs",[["Pioglitazone","Actos"],["Rosiglitazone","Avandia"]],"tzd-names","Thiazolidinedione (TZD)"),
    u("Sensitivity improves slowly",'<p>Increase peripheral insulin sensitivity and muscle/adipose glucose uptake; decrease liver glucose production. They do <strong>not stimulate insulin release</strong>.</p><p>A1C reduction <strong>~0.5–1 point</strong> in this lecture, with several weeks to full effect. Low hypoglycemia risk alone, but <strong>weight gain</strong>.</p>',["tzd-efficacy","tzd-slow","tzd-weight-hypo"],[q("Which efficacy/onset description matches the TZD slides?","~0.5–1 A1C point, with a slow effect over weeks",["Immediate 3-point reduction after one dose","No glucose effect","Identical rapid effect to a meal insulin injection"],"Use the lecture's estimate and delayed response when judging adequacy.")],[q("A patient expects a TZD to act like rapid mealtime insulin on the first day. What explanation is correct?","Sensitivity effects develop over weeks",["Its main role is immediate rescue for low glucose","It directly replaces missing insulin instantly","It lowers every patient's A1C by 4 points"],"TZDs are slowly acting sensitizers, not rapid replacement insulin.")]),
    u("Fluid retention and HF are decisive",'<p>Main adverse effects: <strong>weight gain, edema/fluid retention, worsened HF, and fractures (especially in women)</strong>.</p><p>HF carries a boxed warning; <strong>NYHA III–IV HF is a contraindication</strong>. Low intrinsic hypoglycemia risk does not make the class appropriate for a patient with fluid overload.</p>',["tzd-edema-hf","tzd-fractures","tzd-contra"],[q("Which condition contraindicates TZD therapy in the lecture?","NYHA class III–IV heart failure",["A preference for an oral medicine alone","Any desire to avoid hypoglycemia","Normal kidney function"],"Fluid retention may worsen HF; severe HF is contraindicated.")],[q("A patient with symptomatic advanced HF and edema needs an add-on diabetes drug. Why is a TZD a poor choice?","Fluid retention can worsen HF",["Weight gain always protects the heart","Low hypoglycemia risk overrides HF harm","TZDs are the preferred diuretic agents"],"Consider compelling comorbidity and adverse effects, not glucose lowering alone.")])
  ]);
  add("08-meglitinides","8. Meglitinides","Drug-class objectives: recognize class from names, harms/contraindications, and limited place in therapy. Slides 56–57.",[
    names("Identify the glinides",[["Repaglinide","Prandin"],["Nateglinide","Starlix"]],"glinide-names","Meglitinide"),
    u("Short meal-linked secretion; limited role",'<p>Short-acting beta-cell secretagogues targeting <strong>postprandial glucose</strong>. Take before meals; <strong>skip if the meal is skipped</strong>.</p><p>A1C reduction ~0.5–1 point. Hypoglycemia can occur (may be lower than sulfonylureas); weight gain and repeated meal dosing limit their role versus more beneficial alternatives.</p>',["glinide-meals","glinide-adverse","glinide-place"],[q("What should happen to a meglitinide dose when its meal is skipped?","Skip the dose",["Double it at the usual time","Take it without food to maximize effect","Add a sulfonylurea solely to cover the skipped meal"],"Meal-linked insulin secretion creates low-glucose risk without the meal.")],[q("A patient on repaglinide (Prandin) misses lunch. Which instruction fits?","Skip the lunch-associated dose",["Take a double lunch dose","Take it as usual regardless of intake","Treat it as a weight-neutral DPP-4 drug"],"The drug is a short-acting secretagogue linked to meals.")]),
    u("Contraindication addition",'<p><strong>Label addition for the objective:</strong> repaglinide must not be combined with <strong>gemfibrozil</strong>; it raises drug exposure and low-glucose risk. Avoid a drug with serious hypersensitivity to its ingredients.</p><p>These drugs require working beta cells and are not replacement therapy for T1DM/DKA. <a href="https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=cb995e92-295e-4638-a064-978211f5afe1" target="_blank" rel="noopener noreferrer">Repaglinide label</a>.</p>',["glinide-contra"],[q("Which combination is contraindicated for repaglinide?","Gemfibrozil",["Every nutrition plan","Every appropriate glucose monitor","All exercise"],"Gemfibrozil markedly increases repaglinide exposure.")],[q("A patient taking gemfibrozil is considered for repaglinide. What should guide the decision?","Avoid the contraindicated combination",["Its short duration eliminates the interaction","Take both without reviewing risk","Use doubled repaglinide to compensate"],"A specific label contraindication takes priority over convenient meal dosing.")])
  ]);
  add("09-alpha-glucosidase","9. Alpha-glucosidase inhibitors","Drug-class objectives: identify class, mechanism, and reasons for infrequent use. Slides 59–60.",[
    names("Identify the intestinal enzyme inhibitors",[["Acarbose","Precose"],["Miglitol","Glyset"]],"agi-names","Alpha-glucosidase inhibitor"),
    u("Delay carbohydrate digestion",'<p>Inhibit intestinal enzymes that break down <strong>complex carbohydrates</strong> → delayed glucose absorption and lower postprandial glucose.</p><p>Take with the <strong>first bite of each meal</strong>. A1C reduction ~0.5–0.8 points, weight neutral, low hypoglycemia risk alone.</p>',["agi-moa","agi-timing"],[q("Which action describes acarbose/miglitol?","Delay intestinal carbohydrate digestion and glucose absorption",["Stimulate insulin regardless of glucose","Increase renal glucose excretion","Supply long-acting basal insulin"],"The effect is predominantly on postmeal absorption."),q("When is an alpha-glucosidase inhibitor taken?","With the first bite of a meal",["Only 30 minutes after finishing","Only at bedtime regardless of food","Weekly by injection"],"Timing links the enzyme effect to meal carbohydrates.")],[q("A patient prescribed acarbose (Precose) asks how to time it. Which instruction matches the lecture?","Take with the first bite of each meal",["Take once weekly SQ","Take only after the meal is fully absorbed","Treat it as rapid injected insulin"],"Identify the class and align dosing with carbohydrate digestion.")]),
    u("Why the class is seldom used",'<p><strong>Modest efficacy, frequent meal dosing, and GI effects</strong> limit use: flatulence, diarrhea, abdominal discomfort. Slow titration can improve tolerability.</p><p>Low intrinsic hypoglycemia risk and weight neutrality are advantages, but do not remove the practical GI burden.</p>',["agi-place","agi-gi"],[q("Which combination explains infrequent use?","Modest glucose lowering, GI effects, and frequent dosing",["Guaranteed severe hypoglycemia alone","Major weight gain in every patient","Proven lack of any postmeal effect"],"The class has useful effects but limited potency and tolerability/convenience.")],[q("A patient stops miglitol because of flatulence and difficulty with every-meal doses. Which limitation is illustrated?","GI intolerance plus dosing burden",["A unique requirement for weekly injection","A pronounced insulin peak","Expected severe renal osmotic diuresis"],"These are the lecture's practical reasons for limited use.")])
  ]);
  add("10-insulin-names","10. Insulin: generic and trade names","Insulin objective 1. Slides 71–74: every named insulin and both glargine formulations.",[
    names("Rapid-acting analogs",[["Lispro","Humalog"],["Aspart","NovoLog"],["Glulisine","Apidra"]],"rapid-names","Rapid-acting insulin"),
    names("Regular insulin",[["Regular insulin","Humulin R / Novolin R"]],"regular-names","Short-acting insulin"),
    names("NPH",[["NPH","Humulin N / Novolin N"]],"nph-names","Intermediate-acting insulin"),
    names("Glargine: check concentration",[["Glargine U-100","Lantus / Basaglar / Semglee"],["Glargine U-300","Toujeo"]],"glargine-names","Long-acting basal insulin"),
    names("Degludec",[["Degludec","Tresiba"]],"degludec-names","Ultra-long-acting basal insulin")
  ]);
  add("11-insulin-kinetics","11. Insulin: onset, peak, duration, and timing","Insulin objective 2. Slide 79 table and slides 70–74. Approximate ranges vary by preparation/person.",[
    u("Rapid: early peak for a meal",'<p>Lispro/aspart/glulisine: slide table onset <strong>3–15 minutes</strong>, peak <strong>45–75 minutes</strong>, duration <strong>2–4 hours</strong>.</p><p>Give at/around meals. Fast rise and short action match meal glucose; these are lecture approximations, not identical timing for every product.</p>',["rapid-onset","rapid-peak","rapid-duration","rapid-timing"],[q("Which lecture kinetic pattern matches rapid-acting insulin?","Onset 3–15 min, peak 45–75 min, duration 2–4 hr",["Onset 2 hr, peak 4–12 hr, duration 8–18 hr","No peak and >42 hr duration","Onset 30 min, peak 2–4 hr, duration 5–8 hr"],"An early peak/short duration fits meal-related glucose.")],[q("A patient is about to eat and needs the prescribed rapid mealtime insulin. Why is at/around-meal timing appropriate?","Its onset is fast and its peak is early",["It has a 12-hour delayed peak","It provides only >42-hour basal coverage","It is the same timing as NPH"],"Rapid analogs are used to align insulin action with the meal.")]),
    u("Regular: give ahead of the meal",'<p>Onset <strong>~30 minutes</strong>, peak <strong>2–4 hours</strong>, duration <strong>5–8 hours</strong>.</p><p>Give approximately <strong>30 minutes before meals</strong>. It peaks later and lasts longer than rapid analogs. Regular insulin can also be given IV in the appropriate clinical setting.</p>',["regular-onset","regular-peak","regular-duration","regular-timing","regular-iv"],[q("Which timing/kinetic pairing describes regular insulin?","About 30 min before meals; peak 2–4 hr, duration 5–8 hr",["Weekly with no peak","At the first bite because it blocks intestinal enzymes","Only bedtime with a 4–12 hr peak"],"Regular is slower/longer than rapid analogs.")],[q("A patient changes from a rapid analog to prescribed regular mealtime insulin. Which education difference matters?","Regular generally needs about a 30-minute lead before eating",["Both are always timed identically","Regular is only an ultra-long basal drug","Regular should be delayed until several hours after the meal"],"The onset difference changes how dosing is coordinated with food.")]),
    u("NPH: intermediate action with a pronounced peak",'<p>Onset <strong>~2 hours</strong>, peak <strong>4–12 hours</strong>, duration <strong>8–18 hours</strong> (often ~12 in the slide table).</p><p>Basal coverage once/twice daily. Its pronounced peak increases hypoglycemia risk compared with relatively peakless analogs; anticipate the peak when reviewing glucose patterns.</p>',["nph-onset","nph-peak","nph-duration","nph-timing"],[q("Which kinetic feature distinguishes NPH from long-acting basal analogs?","A pronounced peak around 4–12 hours",["An early 45-minute mealtime peak","No peak with >42 hr duration","No insulin activity after injection"],"NPH peaks rather than remaining relatively flat.")],[q("A patient on NPH has lows at a time compatible with its expected peak. Which formulation feature helps explain the pattern?","Intermediate insulin’s pronounced peak",["NPH is always completely peakless","NPH has no relation to injection timing","NPH works only by urinary glucose loss"],"Align the low pattern with the 4–12-hour peak and review the prescribed plan.")]),
    u("Basal analogs: flatter, longer coverage",table(["Preparation","Approximate profile"],[["Glargine U-100","Onset ~2 hr; relatively no peak; ~20 to >24 hr"],["Glargine U-300","Flatter/prolonged basal action, around/up to 36 hr in the lecture graph"],["Degludec","Onset ~2 hr; minimal peak; >42 hr (slide 74)"]])+'<p>Usually <strong>once daily</strong>. A duration beyond 24 hours does not turn a prescribed daily dose into an every-other-day regimen. Basal coverage is not a rapid meal correction.</p>',["glargine-profile","glargine-u300-profile","degludec-profile","basal-daily"],[q("Which basal insulin has duration >42 hours in the lecture?","Degludec",["Regular insulin","Lispro","NPH"],"Degludec is ultra-long acting with minimal peak."),q("How does the basal analog peak generally differ from NPH?","Relatively flat/minimal peak versus pronounced NPH peak",["Every basal analog peaks within 45 minutes","NPH is flatter than all analogs","Basal analogs have no glucose effect"],"The flatter profile helps explain differences in low-glucose risk.")],[q("A patient assumes degludec can be injected every other day because it lasts >42 hours. What does the lecture’s dosing instruction say?","It is prescribed once daily; long duration does not justify changing the schedule independently",["Every other day is always the recommended regimen","Use it only for immediate meal corrections","Replace it with regular insulin at identical timing"],"Kinetic duration and the prescribed dosing interval are different concepts.")])
  ]);
  add("12-insulin-administration","12. Insulin: administration technique","Insulin objective 3. Slides 66–67, 73, 77–79.",[
    u("Verify the product; prepare it correctly",'<p>Confirm insulin type, <strong>concentration</strong>, and prescribed dose; use the appropriate device. Pens simplify dosing, but technique still matters.</p><p><strong>NPH is cloudy:</strong> gently roll/resuspend it. <strong>Do not mix glargine</strong> with another insulin in the same syringe.</p><p>Refrigerate unopened insulin; do not freeze/overheat. In-use room-temperature life varies by product—check instructions rather than memorizing one expiration for all.</p>',["admin-product-concentration","admin-nph","admin-no-mix","admin-storage"],[q("Which preparation instruction is correct?","Gently resuspend cloudy NPH; do not mix glargine in the same syringe",["Shake every insulin vigorously","Mix glargine with any mealtime insulin","Freeze opened insulin to extend its use"],"Preparation and storage are formulation-specific."),q("Why must insulin concentration be verified?","Products/device instructions differ; concentration mistakes can cause dosing errors",["Every concentration means identical volume and technique","Concentration replaces the prescribed units","Concentrated insulin always means a different drug class"],"Glargine U-100/U-300 and other concentrations require correct product/device use.")],[q("A patient plans to combine glargine and a mealtime insulin into one syringe to save injections. What instruction fits?","Do not mix glargine in the same syringe",["All basal/mealtime combinations may be mixed","Use a larger syringe and mix anyway","Treat mixing as identical to a prescribed premix product"],"Glargine's no-mixing instruction is not the same as a manufactured premix.")]),
    u("Subcutaneous sites and rotation",'<p>Inject into <strong>subcutaneous</strong> abdomen, lateral thigh, buttocks, or upper arm. Avoid IM injection: absorption can become unpredictable and low-glucose risk increases.</p><p>Rotate sites and avoid lipohypertrophy. Short pen needles (e.g., <strong>4 mm</strong>) reduce IM risk. The slide’s pen sequence requires product-specific device instructions.</p>',["admin-sites","admin-subcutaneous","admin-rotation","admin-short-needle"],[q("Which site/route is appropriate for routine injected insulin?","Subcutaneous abdomen, thigh, buttock, or upper arm",["Intentional intramuscular injection for predictability","Injection repeatedly into thickened lipohypertrophy","Only IV use for every home dose"],"Routine home insulin is subcutaneous; rotation and avoiding affected tissue improve absorption.")],[q("A patient repeatedly injects into the same thickened abdominal area and glucose responses vary. What correction is appropriate?","Rotate sites and avoid the lipohypertrophic area",["Use that area more often to stabilize it","Switch to intentional IM injection","Ignore the tissue change because the dose is unchanged"],"Repeated use causes lipohypertrophy and unpredictable absorption.")])
  ]);
  add("13-insulin-uses","13. Insulin: meals, pumps, basal, and correction","Insulin objective 4. Slides 68, 71–74, 80–81.",[
    u("Basal versus meal/correction replacement",'<p><strong>Basal:</strong> long-acting analog or NPH covers between meals/overnight.</p><p><strong>Prandial:</strong> rapid analog or appropriately timed regular covers meals. <strong>Correction:</strong> additional prescribed rapid insulin addresses above-target glucose; do not confuse correction with long basal action.</p>',["use-basal","use-meal","use-correction"],[q("Which pairing correctly matches insulin role?","Basal covers background needs; prandial covers food; correction addresses above-target glucose",["Every role is supplied only by NPH meal peaks","Basal is a rapid rescue for a meal spike","Correction insulin replaces all background insulin in T1DM"],"Different roles approximate normal physiologic secretion.")],[q("Fasting readings are at goal but postmeal glucose repeatedly rises. Which insulin role relates most directly to the meals?","Prandial insulin coverage",["Only extending long-acting basal duration","Stopping all basal insulin","Only changing the injection storage temperature"],"Identify the timing/role before changing a regimen.")]),
    u("Pumps and premixes: different delivery concepts",'<p>Pumps use <strong>rapid-acting insulin for basal infusion and meal/correction boluses</strong>. AID combines pump + CGM + algorithm; it can improve time in range and reduce lows but still requires education/self-management.</p><p>Premixes fix basal/intermediate and mealtime components: 70/30 human = 70% NPH/30% regular; analog mixes also exist. Fewer injections, but less independent dose adjustment and more need for consistent meals.</p>',["use-pump","use-aid","use-premix-tradeoff"],[q("Which insulin generally supplies both basal and bolus delivery in a pump?","Rapid-acting insulin",["Only glargine U-300","Only NPH suspension","Acarbose"],"Continuous infusion supplies basal needs; programmed rapid boluses cover meals/corrections.")],[q("A patient wants fewer injections but has highly variable meals and needs separate basal/meal adjustments. Which premix limitation matters?","Fixed ratios reduce flexibility and increase difficulty with variable intake",["Premixes allow completely independent component adjustment","Premixes eliminate all meal-timing concerns","Premixes are identical to an AID algorithm"],"Convenience must be weighed against fixed-ratio limitations.")])
  ]);
  add("14-insulin-starting-dose","14. Insulin: initial dose and division","Insulin objective 5. Slides 75, 95 plus labeled ADA T1DM weight-based addition.",[
    u("T2DM: starting basal dose",'<p>Common start: <strong>10 units/day OR 0.1–0.2 units/kg/day</strong>, individualized for glucose and low risk.</p><p>Follow fasting glucose trends for basal adjustment. This basal-only start is not a complete T1DM replacement regimen.</p>',["dose-t2-10units","dose-t2-weight"],[q("Which common T2DM basal starting dose is listed?","10 units/day or 0.1–0.2 units/kg/day",["1 unit/kg per meal for every patient","0.5 units/kg entirely as meal insulin","No background insulin can be started in T2DM"],"These are alternative common basal starting approaches.")],[q("An 80-kg T2DM patient is started on basal insulin using 0.1–0.2 units/kg/day. What is the calculated daily range?","8–16 units/day",["80–160 units/day","0.8–1.6 units/day","40–80 units before every meal"],"80 × 0.1–0.2 = 8–16 daily basal units, individualized.")]),
    u("T1DM: total daily dose includes both components",'<p><strong>ADA addition:</strong> a common initial adult basal–bolus estimate is <strong>0.4–0.5 units/kg/day</strong>; new-onset needs vary, often ~0.2–0.6 with residual secretion.</p><p>The lecture divides <strong>~30–50% basal</strong>, remainder prandial/correction. An approximately half-and-half start is one practical pattern, not a rule for every person. '+ada+'</p>',["dose-t1-weight","dose-t1-split","dose-t1-individualized"],[q("How does the lecture divide T1DM total daily insulin?","About 30–50% basal; the remainder prandial/correction",["100% basal with no meal coverage","100% correction only","A mandatory identical split in every person regardless of response"],"The total includes background and meal/correction needs."),q("Which common adult initial total-dose estimate is supplied by the labeled ADA addition?","0.4–0.5 units/kg/day",["10 units/kg/day","0.1–0.2 units/kg for every meal","Exactly 100 units for every patient"],"This is an initial estimate; age, residual secretion, illness, and risk affect actual needs.")],[q("A 60-kg adult uses the example estimate 0.5 units/kg/day and a 50% basal split. What are the calculated total and basal doses?","30 units total/day; 15 units basal/day",["15 units total/day; 30 units basal/day","300 units total/day; 150 basal/day","30 units basal plus 30 units before each meal"],"60 × 0.5 = 30; half is 15 basal, with the remaining 15 allocated to meal/correction needs.")])
  ]);
  add("15-insulin-titration","15. Insulin: outpatient titration","Insulin objective 6. Slide 76.",[
    u("Adjust to trends; reduce for lows",'<p>Basal titration follows <strong>fasting glucose trends</strong>. A common approach is <strong>~2 units every 3–4 days</strong> until fasting glucose is at the individualized goal.</p><p><strong>Decrease for hypoglycemia</strong>; investigate timing, food/activity, kidney function, and delivery. Individualize the protocol rather than increasing every dose mechanically.</p>',["titrate-fasting","titrate-2units","titrate-decrease-low"],[q("Which basal titration approach is taught?","About 2 units every 3–4 days based on fasting trends, with reduction for lows",["Increase daily regardless of lows","Adjust only from a single A1C value","Use postmeal readings alone for every basal change"],"Repeated fasting readings guide background insulin adjustments.")],[q("Fasting readings remain above the individualized goal over several days with no lows on the prescribed plan. What common lecture approach may be used?","A small basal increase, such as ~2 units, with reassessment in 3–4 days",["A large fixed increase regardless of risk","Stop monitoring after the change","Double every meal dose solely because fasting glucose is high"],"Use trends and the prescribed individualized titration framework."),q("A patient titrating basal insulin develops fasting hypoglycemia. What is the appropriate direction of review?","Reduce/reassess rather than continuing automatic increases",["Increase because A1C was previously high","Ignore the low until the next quarterly A1C","Add another basal insulin without assessment"],"Low glucose interrupts upward titration and requires cause/safety review.")])
  ]);
  add("16-insulin-complications","16. Insulin: harms and prevention","Insulin objective 7. Slides 82–84.",[
    u("Hypoglycemia is the main acute harm",'<p>Risk rises with intensive therapy, previous lows, impaired awareness, age/cognitive impairment, CKD, missed meals, and increased activity. Beta blockers can blunt adrenergic warnings.</p><p>Match doses to meals/activity, monitor, review kidney changes and recurrent lows. CGM/AID can reduce risk; do not assume the absence of palpitations excludes a low.</p>',["insulin-hypo-risk","insulin-hypo-prevention","insulin-beta-blocker"],[q("Which factors raise insulin-related hypoglycemia risk?","CKD, missed meals, increased activity, and previous lows",["A normal A1C eliminates all risk","Beta blockers guarantee strong warning palpitations","More insulin always lowers risk"],"Medication effects, food/activity mismatch, and impaired awareness matter.")],[q("A patient with CKD takes insulin, misses dinner, and uses a beta blocker. Why is lack of palpitations not reassuring?","Warnings may be blunted while medication/meal factors raise low risk",["Beta blockers eliminate hypoglycemia","Missing dinner prevents insulin action","CKD guarantees faster insulin clearance"],"Check glucose and assess the high-risk context rather than relying on a warning symptom.")]),
    u("Weight and injection-site complications",'<p>Insulin can cause <strong>weight gain</strong>. Repeated-site use causes lipohypertrophy and variable absorption; rotate and avoid affected tissue.</p><p><strong>Lipoatrophy</strong> is loss of subcutaneous fat and is rare with modern products. Insulin allergy is also rare; assess reactions rather than dismissing them.</p>',["insulin-weight","insulin-lipohypertrophy","insulin-lipoatrophy","insulin-allergy"],[q("Which prevention step addresses lipohypertrophy?","Rotate sites and avoid injecting into affected tissue",["Always use the thickest lump","Give routine IM injections","Freeze opened insulin"],"Site rotation prevents repeated local tissue changes and unpredictable absorption.")],[q("A patient develops a thickened lump at a repeatedly used site and fluctuating glucose responses. Which complication and prevention fit?","Lipohypertrophy; rotate and avoid the affected area",["Lipoatrophy; repeatedly use the same lump","Expected AID behavior; no change needed","A reason to mix glargine with every meal dose"],"Lipohypertrophy enlarges subcutaneous tissue; lipoatrophy is fat loss.")])
  ]);
  add("17-monitoring-devices","17. Glucometer and CGM education","Additional objective 1. Slides 7–8 plus labeled ADA explanation of measurement/use.",[
    u("Meter: a blood-glucose snapshot",'<p>A glucometer uses a <strong>finger-stick blood drop, lancet, and test strip</strong>. It gives the glucose at that moment, useful for treatment checks and safety decisions.</p><p>Practical education addition: clean/dry hands, correct strips and device instructions, record time/results with food/activity/doses, and follow an individualized checking plan based on treatment and low risk.</p>',["meter-purpose","meter-how","meter-use","monitor-log"],[q("What does a standard glucometer measure?","Blood glucose from a finger-stick sample at that time",["A1C continuously through the skin","Interstitial trends without a blood sample","The actual insulin concentration in the pen"],"A meter provides a snapshot rather than a multi-hour trend or A1C.")],[q("A patient records glucose without timing or meal/dose context. Which education improves its usefulness?","Record readings with time, meals/activity, and doses as instructed",["Use only the highest value","Ignore all low values","Treat a meter as continuous overnight trend data"],"Context allows the team to relate glucose changes to the plan.")]),
    u("CGM: sensor values and trends, with meter backup",'<p><strong>ADA addition:</strong> CGM measures interstitial glucose, displaying readings/trends and often alerts. It can lag blood glucose during rapid changes.</p><p>Use sensor/device instructions; interpret trends and respond to alarms using the care plan. Keep a <strong>backup meter</strong> for suspected inaccurate/discordant readings, sensor warm-up, or interruption. <a href="https://doi.org/10.2337/dc26-s007" target="_blank" rel="noopener noreferrer">ADA technology guidance</a>.</p>',["cgm-purpose","cgm-interstitial-lag","cgm-use","cgm-backup"],[q("Why should a CGM user retain a glucometer?","Sensors can be unavailable/inaccurate, and interstitial values may lag rapid blood changes",["CGM measures A1C and cannot show glucose","A sensor eliminates all need for a backup","Every sensor value must equal blood glucose instantly"],"The devices measure related but different compartments and have practical failure/lag situations.")],[q("A patient feels low but the CGM reading seems inconsistent and glucose is changing rapidly. What monitoring step fits the taught plan?","Use the backup meter to check a discordant sensor result and follow the response plan",["Ignore symptoms because the sensor cannot lag","Remove all monitoring permanently","Assume every device measures exactly the same compartment instantly"],"A meter can help clarify a sensor result that does not match the clinical picture.")])
  ]);
  add("18-motivational-interviewing","18. Motivational interviewing and cultural humility","Additional objective 2. Slides 3–6.",[
    u("Collaborate, listen, and make achievable goals",'<p>Ask about beliefs, concerns, and readiness; express empathy and positive regard, and explore advantages of change without arguing with resistance.</p><p>Use <strong>teach-back without quizzing</strong>; adapt to literacy/numeracy, food security, cost/insurance, culture, medication preferences, and family input. Set specific realistic goals <strong>with</strong> the patient; involve chosen supporters and revisit progress.</p>',["mi-empathy","mi-teachback","mi-barriers-culture","mi-shared-goals"],[q("Which approach fits motivational interviewing in the lecture?","Listen to beliefs, explore change, and set specific goals collaboratively",["Argue until the patient accepts a predetermined plan","Quiz the patient to embarrass them into adherence","Ignore cost and food security because a prescription exists"],"Empathy and feasible shared goals support long-term risk reduction.")],[q("A patient is hesitant about injections and cannot afford the suggested device. What is the appropriate first counseling approach?","Explore concerns/access and collaboratively find a feasible plan",["Label the patient nonadherent before listening","Dismiss the concerns and repeat the same demand","Exclude family support the patient wants"],"Preference and access are part of planning, not obstacles to be ignored.")])
  ]);
  add("19-a1c-goal-selection","19. Choose an individualized A1C goal","Additional objective 3. Slides 9–10, 93.",[
    u("Usual, tighter, or less stringent",'<p><strong>&lt;7%</strong> is common for most nonpregnant adults. Consider <strong>&lt;6.5%</strong> when safely achievable with good health/long life expectancy, low low-glucose risk, and low burden.</p><p><strong>&lt;8%</strong> may suit selected patients with frailty, extensive comorbidities, limited life expectancy, or high hypoglycemia risk. Consider resources, support, and preferences; these are individualized rather than age-only rules.</p>',["goal7","goal65","goal8","goal-individualize"],[q("Which patient factors support a less stringent A1C goal in the lecture?","Frailty, limited life expectancy, major comorbidity, or high hypoglycemia risk",["Excellent health with low burden alone","Every adult younger than 35","A desire to ignore monitoring completely"],"The target balances long-term benefit against current harm and burden.")],[q("A frail older adult has multiple comorbidities and recurrent severe lows on a burdensome plan. Which lecture target may be appropriate after individualized review?","A less stringent target such as <8%",["<5% regardless of risk","The tightest achievable value at any cost","A target chosen from age alone without risk assessment"],"A selected less stringent goal can reduce harm and treatment burden."),q("A healthy adult with long life expectancy can achieve tighter control without lows or undue burden. Which target may be considered?","<6.5% if safely achievable",["<8% is mandatory for every adult","No A1C goal should be discussed","All goals must equal exactly 7%"],"Safe tighter control may be appropriate for selected patients.")])
  ]);
  add("20-t2-goals-modalities","20. T2DM goals and all treatment modalities","Additional objective 4. Slides 5, 87, 90; brief ADA surgery addition completes the named modality.",[
    u("Risk reduction uses more than a prescription",'<p>Goals: meet individualized glycemia safely, reduce long-term organ/CV risk, and support weight and quality of life without excessive burden.</p><p><strong>Diet + exercise + DSMES</strong> accompany medication selection. Assess adherence barriers and revisit goals; medication does not replace feasible lifestyle support.</p>',["t2-overall-goals","modality-diet-exercise","modality-medications-dsmes"],[q("Which description captures the overall T2DM approach?","Individualized glucose/risk reduction with lifestyle, education, and appropriate medication",["A1C is the only outcome and all harms are irrelevant","Lifestyle ends once a drug is started","Every patient must receive the same combination"],"The lecture emphasizes long-term risk reduction and person-centered care.")],[q("A patient begins medication and asks whether nutrition/activity counseling is now unnecessary. What principle fits?","Lifestyle and DSMES remain part of treatment for everyone",["All counseling should stop","Only medication names matter now","Exercise has no relation to glucose or BP"],"Combine modalities rather than substituting a prescription for education/support.")]),
    u("Metabolic surgery is another eligible-patient option",'<p><strong>ADA addition for this objective:</strong> metabolic surgery may be considered in appropriate T2DM/obesity patients to improve weight and glycemia. Evaluate suitability, preferences, surgical risk, and access; long-term nutrition/monitoring support remains necessary.</p><p>This card covers the modality, not the separate surgery/perioperative lecture. '+ada+'</p>',["modality-surgery"],[q("Which statement appropriately includes surgery in T2DM treatment?","It is an option for eligible patients, with individualized evaluation and ongoing care",["It removes the need for all future monitoring","It is required in every T2DM patient","It replaces informed preference discussions"],"Surgery is a selected modality rather than a universal treatment.")],[q("A T2DM patient with obesity asks about options beyond medication and lifestyle. Which response fits the objective?","Discuss potential metabolic-surgery eligibility, tradeoffs, and ongoing follow-up",["Claim surgery permanently eliminates every care need","Recommend surgery without assessing preferences/risk","Ignore the option because the objective includes only drugs"],"The objective explicitly includes all modalities, including selected surgical care.")])
  ]);
  add("21-hypoglycemia-management","21. Recognize and manage hypoglycemia","Additional objective 5. Slide 84 and the supplied Hypoglycemia treatment material.",[
    u("Recognize the low and choose a safe route",'<p>Warning symptoms include sweating, tremor, palpitations, and hunger; brain-related symptoms include confusion, behavior/vision changes, seizure, or loss of consciousness.</p><p><strong>Alert and safe to swallow:</strong> 15 g fast carbohydrate, recheck in 15 minutes; repeat if still &lt;70 mg/dL, then meal/snack after recovery.</p><p><strong>Unable to swallow/stupor/LOC:</strong> no oral intake; obtain emergency help and use glucagon or clinical IV dextrose as appropriate. Review the responsible drug/meal/activity pattern.</p>',["hypo-recognition","hypo-oral15","hypo-repeat-recovery","hypo-nonoral"],[q("An alert patient can safely swallow and has glucose 56 mg/dL. Which initial approach fits?","15 g fast carbohydrate and recheck in 15 minutes",["More insulin to prevent a later rise","No treatment until the next A1C","Oral intake only after consciousness is lost"],"Treat and reassess the conscious safely swallowing patient."),q("Which route principle applies to unconscious hypoglycemia?","Non-oral rescue; do not give food/drink by mouth",["Pour juice into the mouth","Place candy under the tongue regardless of swallowing","Wait for hunger before treating"],"Loss of consciousness makes oral intake unsafe.")],[q("A patient on glimepiride has sweating/confusion, improves after treatment, and then has low glucose again. What management concern remains?","Recurrent drug-associated hypoglycemia and ongoing monitoring/reassessment",["Initial improvement excludes another episode","The episode proves insulin was injected","A normal value once ends all safety review"],"Persistent secretagogue action can cause recurrence after initial correction.")])
  ]);
  add("22-hypoglycemia-risk-comparison","22. Compare medication hypoglycemia risk","Additional objective 6. Class clinical-effect slides.",[
    u("High-risk secretion/replacement versus low intrinsic risk",'<p><strong>Higher risk:</strong> insulin and sulfonylureas. Meglitinides also can cause lows, though their shorter action may reduce risk relative to sulfonylureas.</p><p><strong>No/low intrinsic risk alone:</strong> metformin, GLP-1 RA, tirzepatide, DPP-4, SGLT2, TZD, and alpha-glucosidase inhibitors.</p><p>The word <strong>alone</strong> matters: adding insulin or a secretagogue changes the total-regimen risk.</p>',["risk-high-insulin-su","risk-glinide","risk-low-classes","risk-combinations"],[q("Which pair has high intrinsic hypoglycemia risk?","Insulin and sulfonylureas",["Metformin and DPP-4 inhibitors alone","SGLT2 and GLP-1 therapy alone","TZD and alpha-glucosidase inhibitor alone"],"Replacement insulin and glucose-independent secretion carry greater risk."),q("Which statement about a low-risk drug is correct?","Low risk alone does not remove hypoglycemia risk when combined with insulin/secretagogues",["A low-risk add-on cancels all insulin lows","No combination can cause lows","Only A1C determines low risk"],"Assess the whole regimen, not one medication in isolation.")],[q("A patient using metformin, glimepiride, and saxagliptin has repeated lows. Which component has the clearest high-risk mechanism?","Glimepiride",["Metformin as a forced secretagogue","Saxagliptin as injected insulin","All three have identical intrinsic low risk"],"Glimepiride stimulates insulin regardless of glucose; review the full plan and goals.")])
  ]);
  add("23-weight-comparison","23. Compare weight effects","Additional objective 7. Class clinical-effect slides.",[
    u("Gain, neutral, or loss",table(["Pattern","Classes"],[["Gain","Insulin, sulfonylureas, TZDs; meglitinides may also cause gain"],["Neutral","DPP-4 and alpha-glucosidase inhibitors"],["Neutral to modest loss","Metformin"],["Modest loss","SGLT2 inhibitors"],["More substantial loss","GLP-1 receptor agonists and tirzepatide"]])+'<p>Weight is one selection factor alongside comorbidity, safety, efficacy, access, and preference.</p>',["weight-gain-classes","weight-neutral-classes","weight-loss-classes"],[q("Which grouping is weight neutral in the lecture?","DPP-4 and alpha-glucosidase inhibitors",["Insulin and TZDs","Sulfonylureas and insulin","GLP-1 agonists and tirzepatide as exclusively neutral"],"Distinguish neutral agents from gain/loss patterns."),q("Which classes commonly promote weight gain?","Insulin, sulfonylureas, and TZDs",["SGLT2 and GLP-1 only","Metformin and DPP-4 as major gain drugs","Tirzepatide and alpha-glucosidase inhibitors"],"Meglitinides can also cause gain; metformin is neutral/modest loss.")],[q("A patient prioritizes substantial weight loss and accepts a suitable injectable. Which class pattern supports that goal?","GLP-1–based therapy, including appropriate tirzepatide use",["TZD edema/weight gain","Sulfonylurea as the strongest weight-loss drug","Insulin as a reliable weight-loss agent"],"GLP-1/tirzepatide offer meaningful weight benefit when appropriate.")])
  ]);
  add("24-cardiovascular-comparison","24. Compare CV benefit and HF safety","Additional objective 8. Slides 28, 36, 40, 47, 54; labeled current tirzepatide update.",[
    u("Demonstrated benefit must be agent-specific",'<p><strong>GLP-1:</strong> liraglutide, semaglutide, dulaglutide have demonstrated MACE benefit in the lecture. <strong>SGLT2:</strong> selected agents provide HF/CKD and CV protection.</p><p><strong>Label update beyond slide 30:</strong> August 2026 Mounjaro labeling adds MACE risk reduction in high-risk adults with T2DM. Do not infer identical indications for every brand/formulation. '+tirzepatideLabel+'</p>',["cv-glp-proven","cv-sglt-benefit","cv-tirzepatide-update"],[q("Which principle should guide choosing a drug for CV protection?","Select an agent with demonstrated benefit for the patient's condition",["Assume every member of every class has identical CV evidence","Use A1C lowering as proof of HF benefit","Assume low hypoglycemia risk proves MACE reduction"],"Glycemic potency and organ-outcome evidence are different.")],[q("A T2DM patient with prior MI is at glycemic goal but has ASCVD. What medication principle remains relevant?","Consider appropriate agents with demonstrated CV benefit independent of the A1C being at goal",["Never consider organ-protective therapy once A1C is controlled","A sulfonylurea's A1C reduction proves CV benefit","Every agent has identical outcome evidence"],"Compelling comorbidity can drive selection independent of additional glucose lowering.")]),
    u("HF harm differs from glucose benefit",'<p><strong>TZDs:</strong> edema and worsened HF; NYHA III–IV contraindication.</p><p><strong>DPP-4:</strong> no demonstrated CV benefit in the lecture; saxagliptin has increased HF hospitalization, and saxagliptin/alogliptin carry HF warnings.</p><p><strong>Sulfonylureas:</strong> no demonstrated cardiorenal benefit. Choose SGLT2 agents with proven HF benefit when appropriate rather than a drug that aggravates fluid retention.</p>',["cv-tzd-hf","cv-dpp-hf","cv-su-no-benefit"],[q("Which comparison is appropriate in HF?","SGLT2 benefit versus TZD fluid-retention harm and saxagliptin/alogliptin cautions",["Every glucose-lowering class has identical HF benefit","TZDs are preferred because they retain fluid","Saxagliptin is the most clearly proven HF-benefit agent"],"Consider the specific HF outcome/safety profile.")],[q("A patient with HF is taking pioglitazone and saxagliptin. Which review is justified?","Review TZD fluid retention and the DPP-4 HF warning; consider appropriate HF-benefit therapy",["Both drugs are preferred HF-protective therapy","Only current A1C matters","Ignore HF because the drugs are oral"],"Comorbidity safety can require changing an otherwise glucose-effective plan.")])
  ]);
  add("25-efficacy-comparison","25. Compare approximate A1C-lowering strength","Additional objective 9. Class estimates plus the labeled tirzepatide numeric addition.",[
    u("Estimate the gap before choosing potency",table(["Class","Approximate A1C reduction (percentage points)"],[["Metformin; sulfonylureas","~1–1.5"],["GLP-1 receptor agonists","~1–2"],["Tirzepatide","~2 or more in trials; variable"],["DPP-4; alpha-glucosidase inhibitors","~0.5–0.8"],["SGLT2; TZDs; meglitinides","~0.5–1 (lecture estimates)"],["Insulin","High potential; individualized dose/response rather than one fixed reduction"]])+'<p>Effects vary by starting A1C, agent/dose, adherence, and patient. Do not promise a fixed result or simply add class estimates as exact arithmetic.</p>',["efficacy-all-classes","efficacy-gap","efficacy-variable"],[q("Which drug class is least likely by itself to close a 2-point A1C gap using the lecture's usual estimates?","DPP-4 inhibitor (~0.5–0.8)",["Tirzepatide with very high efficacy","An appropriately intensified insulin plan","A potent GLP-1 option may offer more lowering"],"Match expected strength to the gap without promising an exact result.")],[q("A patient is 2 points above goal. An add-on with expected reduction of 0.5–0.8 points is proposed as guaranteed sufficient. What is the concern?","Its usual potency may not close the gap; the claim is too certain",["Every drug always lowers A1C exactly 2 points","A1C gaps never guide treatment","Starting A1C cannot affect response"],"Use potency, combination needs, and reassessment rather than guarantees.")])
  ]);
  add("26-initial-add-on-therapy","26. Select initial and add-on T2DM therapy","Additional objective 10. Slides 87–91.",[
    u("Comorbidities first; then distance from goal",'<p>Start with lifestyle/DSMES and assess <strong>ASCVD, HF, CKD</strong>. Appropriate organ-benefit therapies can be indicated regardless of A1C or metformin use.</p><p>Without a compelling driver, set the individualized goal: <strong>&lt;1.5 points above goal → generally one agent; ≥1.5 points → consider initial combination</strong>. Metformin is a common first-line choice when no other factor selects differently.</p>',["initial-comorbidity-first","initial-gap15","initial-metformin"],[q("Without a compelling comorbidity, when does the lecture suggest considering initial combination therapy?","A1C ≥1.5 points above the individualized goal",["Only after A1C exceeds 15%","Every patient regardless of gap","Never before an insulin pump"],"The gap helps decide initial treatment intensity.")],[q("A T2DM patient has goal <7%, A1C 9%, and no known ASCVD/HF/CKD. Which starting intensity should be considered?","Combination therapy because the gap is 2 points",["Only the weakest agent because all responses are identical","No treatment until symptoms develop","A1C 9% automatically requires a T1DM pump"],"A 2-point gap exceeds the ≥1.5-point combination threshold.")]),
    u("Add-on treatment reviews the person, not just the number",'<p>Before adding a drug, review comorbidities, adherence/technique, weight goals, low risk, adverse effects, renal function, cost/access, and willingness/preferences.</p><p>For most patients needing an injectable without severe hyperglycemia/crisis, <strong>GLP-1–based therapy is preferred before insulin</strong>. Avoid unhelpful DPP-4 + GLP-1 combinations.</p>',["addon-patient-factors","addon-injectable","addon-combination-review"],[q("Which injectable approach is generally preferred before insulin when severe hyperglycemia/crisis is absent?","GLP-1–based therapy when appropriate",["Insulin is mandatory in every T2DM case","DPP-4 plus GLP-1 must always be combined","Only NPH regardless of preferences"],"The lecture favors GLP-1–based therapy first in this context.")],[q("A patient on metformin has A1C 7.9% and needs an add-on. What should be assessed before naming a drug?","Comorbidities, weight/low-risk goals, renal safety, adherence, access, and preference",["Age alone determines one universal agent","Always add saxagliptin without history","Only the highest-cost agent can work"],"Selection requires the clinical and practical context.")])
  ]);
  add("27-compelling-patient-factors","27. Select therapy for compelling patient factors","Additional objective 11. Slides 87–90 and class safety/benefit material.",[
    u("ASCVD, HF, and CKD",'<p><strong>ASCVD/high risk:</strong> suitable GLP-1 and/or SGLT2 agents with proven CV benefit. ASCVD includes coronary MI/ACS/revascularization, ischemic stroke/TIA, and PAD.</p><p><strong>HF:</strong> SGLT2 benefit. <strong>CKD:</strong> appropriate SGLT2 and/or GLP-1 agents with kidney/CV benefit, respecting product renal eligibility and changing glycemic efficacy.</p>',["factor-ascvd","factor-hf","factor-ckd","ascvd-definition"],[q("Which patient factor most specifically favors an appropriate SGLT2 inhibitor in the lecture?","Heart failure",["A need to increase fluid retention","A plan to replace all insulin in T1DM","A history requiring avoidance of all osmotic diuresis without review"],"The class has demonstrated HF benefit in eligible patients."),q("Which condition belongs to ASCVD?","Prior ischemic stroke or PAD",["Only isolated seasonal allergies","Only benign thyroid enlargement","Only routine nausea"],"Coronary, cerebrovascular, and peripheral arterial disease are included.")],[q("A patient with T2DM, HF, and CKD has A1C near goal. Which selection strategy fits?","Assess eligibility for an SGLT2 agent with HF/kidney benefit rather than using A1C alone",["Exclude organ-benefit therapy because A1C is controlled","Choose a TZD specifically to retain fluid","Ignore renal function when selecting the product"],"Compelling conditions can guide therapy independent of glucose-lowering need.")]),
    u("Weight, lows, adverse effects, access, and preference",'<p>Weight loss: appropriate GLP-1/tirzepatide or modest-loss SGLT2 options. Avoiding lows: favor low-intrinsic-risk agents and reassess insulin/secretagogues.</p><p>Safety and tolerability can override an appealing benefit (e.g., HF/TZD, MTC/warned incretin product). Match cost, insurance, route, and achievable use to preferences; make a shared plan.</p>',["factor-weight","factor-hypo","factor-adverse","factor-cost-preference"],[q("Which is the best general selection principle?","Balance benefit with contraindications, low risk, access, and preferences",["Weight loss overrides every contraindication","The cheapest drug is mandatory despite repeated severe lows","Route preference replaces all clinical assessment"],"Treatment should be both clinically appropriate and feasible.")],[q("A patient wants weight loss but has a contraindication to a proposed GLP-1 product and cannot afford another preferred option. What approach fits?","Review safe feasible alternatives collaboratively, rather than overriding the contraindication",["Prescribe the contraindicated drug because weight benefit wins","Ignore access and provide no alternative","Use the same regimen for every patient"],"Safety and real-world feasibility remain part of individualized treatment.")])
  ]);
  add("28-t2-insulin-start-adjust","28. T2DM: when to start insulin and how to adjust","Additional objective 12. Slides 75–76, 91; integrates the earlier dose/titration cards.",[
    u("Recognize the need for insulin",'<p>Consider insulin with <strong>significant hyperglycemic symptoms, A1C &gt;10%, glucose ≥300 mg/dL, catabolism (weight loss/ketosis), or unmet goals despite noninsulin therapy</strong>.</p><p>Start a suitable basal plan (often 10 units/day or 0.1–0.2 units/kg/day) and titrate fasting trends, reducing for lows. Severe/crisis presentations require assessment, not routine outpatient titration alone.</p>',["t2-insulin-indications","t2-insulin-start","t2-insulin-adjust"],[q("Which findings strongly support considering insulin in T2DM?","A1C >10%, glucose ≥300, symptoms, and unexpected weight loss/ketosis",["A1C 6.6% alone without other context","A preference for oral therapy automatically rules it out","Controlled fasting glucose with no other concern"],"Marked glucose burden and catabolism are lecture-listed triggers.")],[q("A new T2DM patient has A1C 11.4%, fasting glucose 326 mg/dL, polyuria, thirst, and unintentional weight loss. Which treatment consideration fits?","Insulin should be considered, with assessment of severity and an individualized initiation plan",["Only a weak add-on is sufficient by definition","Weight loss excludes any insulin need","Wait without treatment until the next routine annual screen"],"This case combines marked hyperglycemia, symptoms, and catabolism."),q("After basal initiation, repeated fasting lows occur. How should the outpatient plan change?","Reassess the cause and decrease the responsible insulin rather than escalating",["Increase automatically because initial A1C was high","Ignore readings because starting dose was weight-based","Treat CGM/meter data as irrelevant to titration"],"Starting-dose calculations do not override subsequent safety data.")])
  ]);
  add("29-t1-insulin-trends","29. T1DM: physiologic dosing and changing needs","Additional objective 13. Slides 93–95.",[
    u("Replace physiology; anticipate the honeymoon",'<p>MDI uses <strong>long-acting basal + rapid meal/correction insulin</strong>. Pump/AID uses rapid insulin for both basal infusion and boluses; CGM supports most patients.</p><p>Needs depend on age, weight, activity, and illness. During partial remission, residual beta-cell secretion temporarily improves: <strong>insulin needs decrease, but insulin continues</strong>. As endogenous secretion declines, needs rise again.</p>',["t1-physiologic","t1-needs-factors","t1-honeymoon","t1-continue-insulin"],[q("What happens during the T1DM honeymoon phase?","Temporary residual secretion lowers dose needs, but insulin must continue",["Autoimmunity is permanently cured and insulin always stops","All patients require immediate doubling","Only basal insulin is ever needed again"],"Partial remission changes dose needs without ending the replacement requirement."),q("Which regimen most closely replaces physiologic T1DM needs?","Basal plus prandial/correction, through MDI or appropriate rapid-insulin pump/AID",["Only intermittent correction without basal","A sulfonylurea replaces absent beta cells","Only a weekly GLP-1 drug in place of insulin"],"Background and meal/correction needs both require replacement.")],[q("Soon after starting insulin, a T1DM patient's requirements fall during partial remission. Which plan principle is appropriate?","Adjust doses to current needs while continuing insulin and monitoring",["Declare cure and stop all insulin indefinitely","Ignore low readings because T1DM always needs the same dose","Replace insulin with an alpha-glucosidase inhibitor"],"Residual secretion can temporarily reduce doses; ongoing individualized replacement remains necessary.")])
  ]);
  window.DIABETIC_PHARMACOLOGY_OBJECTIVES=sections;
})();
